templates.front:
{{#Sentence1}}

<div id="sentence">{{Sentence1}}</div>
<br>{{Sentence1 Audio}}

{{/Sentence1}}




<script>
var el = document.getElementById("sentence");
if (el) {
var fullSentence = el.innerHTML;

function showBoldOnly() {
  var bolds = [...el.querySelectorAll("b")];

  if (!bolds.length) { showFullSentence(); return; }
  el.innerHTML = bolds
    .map((b, i) =>
      `${i ? ' <span class="separator">/</span> ' : ''}${b.outerHTML}`
    )
    .join('');

  el.classList.remove("expanded");
}

function showFullSentence() {
  el.innerHTML = fullSentence;
  el.classList.add("expanded");
}

el.addEventListener("click", () => {
  if (el.classList.contains("expanded")) {
    showBoldOnly();
  } else {
    showFullSentence();
  }
});

showBoldOnly();
}
</script>

